#Covariance_Matrix
Covariance_Matrix = []
for i in Data1:
  Data = np.asarray(Data1[i])
  conv = np.zeros([2,2])
  for k in range(0, 2):
    for j in range(0, 2):
      a = Data[:][:,k]
      b = Data[:][:,j]
      a_mean = np.mean(a)
      b_mean = np.mean(b)
      sum = 0
      for l in range(0, len(a)):
          sum += ((a[l] - a_mean) * (b[l] - b_mean))
      #print(sum/len(a)-1)
      conv[k][j] = sum/(len(a)-1)
  Covariance_Matrix.append(conv)

