## ROC curve

M = 1050
N = 3

S = np.zeros((M,N))

print(LData.shape)

def multivariate_gaussian2(pos, mu, Sigma):
    n = mu.size
    Sigma_det = np.linalg.det(Sigma)
    Sigma_inv = np.linalg.inv(Sigma)
    N = np.sqrt((2*np.pi)**n * Sigma_det)
    fac = ((pos-mu).T)@(Sigma_inv)@(pos-mu)
    return np.exp(-fac/2)/N


for i in range(M):
  for j in range(N):
    S[i,j] = multivariate_gaussian2(LData[i,0:2],np.asarray(meu[j]),np.asarray(conv))/3

min = np.amin(S)
max = np.amax(S)

TPR11 = []
FPR11 = []

thresholds = np.linspace(min,max,100)

for threshold in thresholds:
  TP = FP = TN = FN = 0
  for i in range(M): 
    for j in range(N):
      if S[i,j] >= threshold:
        if LData[i,2] == j+1:
          TP+=1
        else:
          FP+=1
      else:
        if LData[i,2] == j+1:
          FN+=1 
        else:
          TN+=1
  TPR11.append(TP/(TP+FN))  # True positive rate
  FPR11.append(FP/(FP+TN))  # False positive rate

print(S)
print(FPR11)  
print(TPR11) 

# plotting
plt.title("ROC curve")
plt.xlabel("FPR")
plt.ylabel("TPR")
plt.plot(FPR11, TPR11, color ="green")
plt.show()

